function saveFile(name,data,type){
  const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([data],{type}));a.download=name;document.body.appendChild(a);a.click();
  setTimeout(()=>{URL.revokeObjectURL(a.href);a.remove()},1000);
}
function libraryInfoOf(lib){const L=Object.assign({},lib.library||{});delete L.shelves;delete L.yearlyGoal;return L}
function exportLibrary(){
  if(!window.BookFormat){toast('רכיב הפורמט לא נטען');return}
  const lib=BookFormat.toLibrary(meta,books,libInfo||BookFormat.DEFAULT_LIBRARY);
  saveFile('library.json',JSON.stringify(lib,null,2)+'\n','application/json');
  toast('הקובץ library.json נשמר בתיקיית ההורדות');
}
function resetToBaseline(){
  const base=window.BOOKSHELF_BASELINE;
  if(!base||!window.BookFormat){toast('לא נמצא קובץ נקודת ההתחלה (data/library.js)');return}
  $('dlg').innerHTML=`<div class="dbody"><h3>חזרה לנקודת ההתחלה</h3><p>הארון יחזור למצב שבקובץ data/library.json (${base.books.length} ספרים). כל השינויים שנעשו מאז במחשב הזה יימחקו.</p><p style="color:var(--muted);font-size:14px">כדי לשמור אותם, קודם ייצאו לקובץ library.json.</p><div class="actions"><span class="grow"></span><button id="cancel">ביטול</button><button class="danger" id="go">לחזור להתחלה</button></div></div>`;
  $('ov').classList.add('open');$('cancel').onclick=close;
  $('go').onclick=()=>{loadLibrary(base);persistLocal();close();toast('הארון חזר לנקודת ההתחלה')};
}
function loadLibrary(lib){const d=BookFormat.fromLibrary(lib);libInfo=libraryInfoOf(lib);meta=d.meta;books=d.books.map(b=>Object.assign({id:b.id},clean(b)))}
async function exportBackup(){
  const data=JSON.stringify({app:'bookshelf',version:2,exported:new Date().toISOString(),meta:{shelves:meta.shelves,goal:meta.goal||0},books:books.map(b=>Object.assign({id:b.id},clean(b)))},null,1);
  const name='גיבוי-ארון-ספרים-'+today()+'.json';
  if(downloads){try{await downloads.save({filename:name,data});toast('הגיבוי נשמר');return}catch(e){if(e&&e.code==='declined')return}}
  if(localMode){saveFile(name,data,'application/json');toast('הגיבוי נשמר בתיקיית ההורדות');return}
  $('dlg').innerHTML=`<div class="dbody"><h3>גיבוי הארון</h3><p style="color:var(--muted);font-size:14px">אפשר להעתיק את הטקסט ולשמור אותו כקובץ.</p><textarea id="bk" rows="8" style="width:100%;direction:ltr;font-size:11px" readonly></textarea><div class="actions"><span class="grow"></span><button id="cp">העתקה</button><button class="primary" id="cancel">סגירה</button></div></div>`;
  $('bk').value=data;$('ov').classList.add('open');$('cancel').onclick=close;
  $('cp').onclick=async()=>{try{await navigator.clipboard.writeText(data);toast('הועתק')}catch(e){$('bk').select();toast('סמן והעתק ידנית')}};
}
function importBackup(){
  const f=$('impFile');f.value='';f.onchange=async()=>{
    const file=f.files[0];if(!file)return;let d;
    try{d=JSON.parse(await file.text());if(d&&d.format==='bookshelf-library'){libInfo=libraryInfoOf(d);d=BookFormat.fromLibrary(d)}if(!d||!Array.isArray(d.books)||!d.meta)throw 0}catch(e){toast('הקובץ אינו גיבוי תקין של הארון');return}
    $('dlg').innerHTML=`<div class="dbody"><h3>ייבוא מגיבוי</h3><p>בגיבוי יש ${d.books.length} ספרים ו-${(d.meta.shelves||[]).length} מדפים. הייבוא יחליף את כל מה שיש עכשיו בארון (${books.length} ספרים).</p><div class="actions"><span class="grow"></span><button id="cancel">ביטול</button><button class="primary" id="go">להחליף</button></div></div>`;
    $('ov').classList.add('open');$('cancel').onclick=close;
    $('go').onclick=async()=>{
      const bt=$('go');bt.disabled=true;
      meta={shelves:(d.meta.shelves||[]).map(s=>({id:String(s.id)})),goal:+d.meta.goal||0};saveMeta();
      const keep=new Set(d.books.map(b=>String(b.id)));
      const old=books.filter(b=>!keep.has(b.id)).map(b=>b.id);
      let n=0;for(const b of d.books){writeBook(String(b.id),b);if(++n%10===0){bt.textContent=`מייבא... ${n}/${d.books.length}`;await new Promise(r=>setTimeout(r,50))}}
      old.forEach(removeBook);
      close();toast('הארון שוחזר מהגיבוי');
    };
  };f.click();
}
